changeSet.sql:
UPDATE board_tasks SET status = 'BACKLOG' WHERE status IN ('ANALYTICS', 'TODO');
UPDATE board_tasks SET status = 'IN_PROGRESS' WHERE status = 'BLOCKED';

ALTER TABLE board_tasks DROP CONSTRAINT chk_board_tasks_status;
ALTER TABLE board_tasks
    ADD CONSTRAINT chk_board_tasks_status CHECK (status IN ('BACKLOG', 'IN_PROGRESS', 'REVIEW', 'DONE'));
